package com.rustyledger;

import com.rustyledger.impl.LedgerImpl;

public final class RustyLedger {
    private RustyLedger() {}
    public static Ledger openLedger() {
        return new LedgerImpl();
    }
}

package com.rustyledger.impl;

import com.rustyledger.Ledger;
import java.math.BigDecimal;
import java.util.*;

public class LedgerImpl implements Ledger {
    private final Map<String, Object[]> accounts = new HashMap<>();
    private final Map<String, BigDecimal> used = new HashMap<>();
    private final Map<String, String[]> txs = new LinkedHashMap<>();
    private final List<String> audit = new ArrayList<>();
    private final Map<String, int[]> counts = new HashMap<>();
    private final Map<String, Map<String, BigDecimal>> fees = new HashMap<>();
    private int auditSeq = 0;
    private int txSeq = 0;

    public void openAccount(String id, String tier, String currency, String balance) {
        if (id == null || id.trim().isEmpty() || id.indexOf('|') >= 0) throw new IllegalArgumentException();
        if (!Set.of("STANDARD", "PREMIUM", "STAFF").contains(tier)) throw new IllegalArgumentException();
        if (!Set.of("PLN", "EUR", "USD").contains(currency)) throw new IllegalArgumentException();
        if (balance == null || !balance.matches("\\d+(\\.\\d{1,2})?")) throw new IllegalArgumentException();
        if (accounts.containsKey(id)) throw new IllegalStateException();
        accounts.put(id, new Object[]{tier, currency, new BigDecimal(balance).setScale(2)});
    }

    public String balance(String id) {
        Object[] a = accounts.get(id);
        if (a == null) throw new IllegalArgumentException();
        return a[2] + " " + a[1];
    }

    public List<String> auditLog() { return new ArrayList<>(audit); }

    public String dailyReport(String date) {
        int[] c = counts.getOrDefault(date, new int[2]);
        Map<String, BigDecimal> f = fees.get(date);
        String feeText = (f == null || f.isEmpty()) ? "none" : formatFees(f);
        return "REPORT " + date + "\nok: " + c[0] + "\nrejected: " + c[1] + "\nfees: " + feeText;
    }

    private String formatFees(Map<String, BigDecimal> f) {
        StringBuilder sb = new StringBuilder();
        TreeMap<String, BigDecimal> sorted = new TreeMap<>(f);
        for (var e : sorted.entrySet()) {
            if (sb.length() > 0) sb.append(", ");
            sb.append(e.getValue()).append(" ").append(e.getKey());
        }
        return sb.toString();
    }

    public String submit(String line) {
        return new InstructionProcessor(this).process(line);
    }

    public Map<String, Object[]> getAccounts() { return accounts; }
    public Map<String, BigDecimal> getUsed() { return used; }
    public Map<String, String[]> getTxs() { return txs; }
    public List<String> getAudit() { return audit; }
    public Map<String, int[]> getCounts() { return counts; }
    public Map<String, Map<String, BigDecimal>> getFees() { return fees; }
    public int getAuditSeq() { return ++auditSeq; }
    public int getTxSeq() { return ++txSeq; }
}

package com.rustyledger.impl;

import java.math.BigDecimal;

public class InstructionProcessor {
    private final LedgerImpl l;
    public InstructionProcessor(LedgerImpl l) { this.l = l; }

    public String process(String line) {
        if (line == null || line.trim().isEmpty()) return reject("???", null, "BAD_INSTRUCTION", "empty instruction");
        String[] f = line.split("\\|", -1);
        if (!Set.of("TRANSFER", "WITHDRAW", "DEPOSIT", "REVERSE").contains(f[0])) 
            return reject("???", null, "BAD_INSTRUCTION", "unknown verb " + f[0]);
        // Simple delegation to specific handlers based on verb
        if (f[0].equals("REVERSE")) return new ReverseHandler(l).handle(f);
        return new TransferHandler(l).handle(f);
    }

    public String reject(String v, String d, String c, String m) {
        if (d != null) {
            l.getCounts().computeIfAbsent(d, k -> new int[2])[1]++;
        }
        l.getAudit().add(String.format("%03d  %s %s REJECTED %s", l.getAuditSeq(), v, d == null ? "????-??-??" : d, c));
        return "REJECTED " + c + ": " + m;
    }
}

