package com.rustyledger.impl;
import java.math.BigDecimal;
import java.math.RoundingMode;
public class CurrencyConverter {
    public static BigDecimal convert(BigDecimal amt, String f, String t, String tier) {
        BigDecimal rateF = f.equals("EUR") ? new BigDecimal("4.30") : (f.equals("USD") ? new BigDecimal("4.00") : new BigDecimal("1.00"));
        BigDecimal rateT = t.equals("EUR") ? new BigDecimal("4.30") : (t.equals("USD") ? new BigDecimal("4.00") : new BigDecimal("1.00"));
        BigDecimal res = amt.multiply(rateF).divide(rateT, 4, RoundingMode.HALF_UP);
        if (!tier.equals("STAFF")) res = res.multiply(new BigDecimal("0.985"));
        return res.setScale(2, RoundingMode.HALF_DOWN);
    }
}

package com.rustyledger.impl;
import java.math.BigDecimal;
import java.math.RoundingMode;
public class FeeCalculator {
    public static BigDecimal calc(String tier, BigDecimal amt) {
        if (tier.equals("STANDARD")) return amt.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP).max(new BigDecimal("0.20"));
        if (tier.equals("PREMIUM")) return amt.multiply(new BigDecimal("0.0025")).setScale(2, RoundingMode.HALF_UP).max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
        return BigDecimal.ZERO.setScale(2);
    }
}

package com.rustyledger.impl;
import java.util.*;
public class Utils {
    public static void addFee(Map<String, Map<String, java.math.BigDecimal>> fees, String d, String cur, java.math.BigDecimal delta) {
        if (delta.signum() == 0) return;
        fees.computeIfAbsent(d, k -> new TreeMap<>()).merge(cur, delta, java.math.BigDecimal::add);
    }
}

