package com.rustyledger.impl;

public class ReverseHandler {
    private final LedgerImpl l;
    public ReverseHandler(LedgerImpl l) { this.l = l; }
    public String handle(String[] f) {
        if (f.length != 3) return l.getProc().reject("REVERSE", "????-??-??", "BAD_INSTRUCTION", "REVERSE needs 3 fields");
        String date = f[1], txId = f[2];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) return l.getProc().reject("REVERSE", date, "BAD_DATE", date);
        String[] tx = l.getTxs().get(txId);
        if (tx == null) return l.getProc().reject("REVERSE", date, "UNKNOWN_TX", txId);
        if (tx[0].equals("REVERSE")) return l.getProc().reject("REVERSE", date, "NOT_REVERSIBLE", txId + " is a REVERSE");
        if (!tx[1].equals(date)) return l.getProc().reject("REVERSE", date, "REVERSAL_WINDOW", txId + " was made on " + tx[1]);
        if (l.getTxs().containsKey("REV-" + txId)) return l.getProc().reject("REVERSE", date, "ALREADY_REVERSED", txId);
        return l.executeReversal(date, txId, tx);
    }
}

