package com.rustyledger.impl;

import java.math.BigDecimal;
import java.util.*;

public class TransferHandler {
    private final LedgerImpl l;
    public TransferHandler(LedgerImpl l) { this.l = l; }

    public String handle(String[] f) {
        String verb = f[0];
        int req = verb.equals("TRANSFER") ? 6 : 4;
        if (f.length != req) return l.proc.reject(verb, f[1], "BAD_INSTRUCTION", verb + " needs " + req + " fields");
        if (!f[1].matches("\\d{4}-\\d{2}-\\d{2}")) return l.proc.reject(verb, f[1], "BAD_DATE", f[1]);
        String date = f[1], accId = f[2];
        Object[] acc = l.getAccounts().get(accId);
        if (acc == null) return l.proc.reject(verb, date, "UNKNOWN_ACCOUNT", accId);
        BigDecimal amt;
        try {
            amt = new BigDecimal(f[verb.equals("TRANSFER") ? 4 : 3]);
            if (amt.signum() <= 0 || amt.scale() > 2) throw new Exception();
        } catch (Exception e) { return l.proc.reject(verb, date, "BAD_AMOUNT", f[verb.equals("TRANSFER") ? 4 : 3]); }

        if (verb.equals("TRANSFER")) {
            String toId = f[3];
            Object[] to = l.getAccounts().get(toId);
            if (to == null) return l.proc.reject(verb, date, "UNKNOWN_ACCOUNT", toId);
            if (accId.equals(toId)) return l.proc.reject(verb, date, "SAME_ACCOUNT", "cannot transfer to the same account");
            if (!acc[1].equals(f[5])) return l.proc.reject(verb, date, "CURRENCY_MISMATCH", accId + " holds " + acc[1]);

            BigDecimal fee = FeeCalculator.calc((String)acc[0], amt);
            BigDecimal total = amt.add(fee);
            if (((BigDecimal)acc[2]).subtract(total).compareTo(new BigDecimal(acc[0].equals("PREMIUM") ? "-500.00" : "0.00")) < 0)
                return l.proc.reject(verb, date, "INSUFFICIENT_FUNDS", "balance " + acc[2] + " " + acc[1] + ", needed " + total + " " + acc[1]);

            acc[2] = ((BigDecimal)acc[2]).subtract(total);
            BigDecimal converted = CurrencyConverter.convert(amt, (String)acc[1], (String)to[1], (String)acc[0]);
            to[2] = ((BigDecimal)to[2]).add(converted);

            int txNum = l.nextTx();
            l.getTxs().put("TX-" + String.format("%06d", txNum), new String[]{verb, date, accId, toId, amt.toString(), (String)acc[1], fee.toString()});
            Utils.addFee(l.getFees(), date, (String)acc[1], fee);
            return finalize(verb, date, txNum, fee, (String)acc[1]);
        }
        return "OK";
    }

    private String finalize(String v, String d, int n, BigDecimal f, String c) {
        l.getAudit().add(String.format("%03d  %s %s OK TX-%06d", l.nextAudit(), v, d, n));
        l.getCounts().computeIfAbsent(d, k -> new int[2])[0]++;
        return "OK TX-" + String.format("%06d", n) + " fee=" + f + " " + c;
    }
}

