package com.rustyledger.impl;
import java.math.BigDecimal;
import java.util.*;
public class TransferHandler {
    private final LedgerImpl l;
    public TransferHandler(LedgerImpl l) { this.l = l; }
    public String handle(String[] f) {
        String v = f[0];
        if (v.equals("DEPOSIT")) return doDeposit(f);
        if (v.equals("WITHDRAW")) return doWithdraw(f);
        return doTransfer(f);
    }
    private String doDeposit(String[] f) {
        if (f.length != 4) return l.getProc().reject("DEPOSIT", f[1], "BAD_INSTRUCTION", "DEPOSIT needs 4 fields");
        if (!f[1].matches("\\d{4}-\\d{2}-\\d{2}")) return l.getProc().reject("DEPOSIT", f[1], "BAD_DATE", f[1]);
        if (!f[3].matches("\\d+(\\.\\d{1,2})?")) return l.getProc().reject("DEPOSIT", f[1], "BAD_AMOUNT", f[3]);
        Object[] acc = l.getAccounts().get(f[2]);
        if (acc == null) return l.getProc().reject("DEPOSIT", f[1], "UNKNOWN_ACCOUNT", f[2]);
        BigDecimal amt = new BigDecimal(f[3]);
        if (amt.signum() == 0) return l.getProc().reject("DEPOSIT", f[1], "BAD_AMOUNT", f[3]);
        acc[2] = ((BigDecimal)acc[2]).add(amt);
        return l.finalize(f[0], f[1], BigDecimal.ZERO, (String)acc[1]);
    }
    private String doWithdraw(String[] f) {
        if (f.length != 4) return l.getProc().reject("WITHDRAW", f[1], "BAD_INSTRUCTION", "WITHDRAW needs 4 fields");
        if (!f[1].matches("\\d{4}-\\d{2}-\\d{2}")) return l.getProc().reject("WITHDRAW", f[1], "BAD_DATE", f[1]);
        if (!f[3].matches("\\d+(\\.\\d{1,2})?")) return l.getProc().reject("WITHDRAW", f[1], "BAD_AMOUNT", f[3]);
        Object[] acc = l.getAccounts().get(f[2]);
        if (acc == null) return l.getProc().reject("WITHDRAW", f[1], "UNKNOWN_ACCOUNT", f[2]);
        BigDecimal amt = new BigDecimal(f[3]);
        if (amt.signum() == 0) return l.getProc().reject("WITHDRAW", f[1], "BAD_AMOUNT", f[3]);
        BigDecimal fee = acc[0].equals("STANDARD") ? new BigDecimal("1.00") : BigDecimal.ZERO;
        BigDecimal total = amt.add(fee);
        if (((BigDecimal)acc[2]).subtract(total).compareTo(BigDecimal.ZERO) < 0)
            return l.getProc().reject("WITHDRAW", f[1], "INSUFFICIENT_FUNDS", "balance " + acc[2] + " " + acc[1] + ", needed " + total + " " + acc[1]);
        acc[2] = ((BigDecimal)acc[2]).subtract(total);
        return l.finalize(f[0], f[1], fee, (String)acc[1]);
    }
    private String doTransfer(String[] f) {
        if (f.length != 6) return l.getProc().reject("TRANSFER", f[1], "BAD_INSTRUCTION", "TRANSFER needs 6 fields");
        if (!f[1].matches("\\d{4}-\\d{2}-\\d{2}")) return l.getProc().reject("TRANSFER", f[1], "BAD_DATE", f[1]);
        Object[] acc = l.getAccounts().get(f[2]);
        if (acc == null) return l.getProc().reject("TRANSFER", f[1], "UNKNOWN_ACCOUNT", f[2]);
        if (!f[4].matches("\\d+(\\.\\d{1,2})?")) return l.getProc().reject("TRANSFER", f[1], "BAD_AMOUNT", f[4]);
        BigDecimal amt = new BigDecimal(f[4]);
        if (amt.signum() == 0) return l.getProc().reject("TRANSFER", f[1], "BAD_AMOUNT", f[4]);
        Object[] to = l.getAccounts().get(f[3]);
        if (to == null) return l.getProc().reject("TRANSFER", f[1], "UNKNOWN_ACCOUNT", f[3]);
        if (f[2].equals(f[3])) return l.getProc().reject("TRANSFER", f[1], "SAME_ACCOUNT", "cannot transfer to the same account");
        if (!acc[1].equals(f[5])) return l.getProc().reject("TRANSFER", f[1], "CURRENCY_MISMATCH", f[2] + " holds " + acc[1]);
        BigDecimal fee = FeeCalculator.calc((String)acc[0], amt);
        BigDecimal limit = acc[0].equals("STANDARD") ? new BigDecimal("5000") : (acc[0].equals("PREMIUM") ? new BigDecimal("20000") : new BigDecimal("50000"));
        BigDecimal used = l.getDailyUsage().getOrDefault(f[1], new HashMap<>()).getOrDefault(f[2], BigDecimal.ZERO);
        if (used.add(amt).compareTo(limit) > 0) return l.getProc().reject("TRANSFER", f[1], "LIMIT_EXCEEDED", "daily limit " + limit + ".00 for " + acc[0]);
        BigDecimal total = amt.add(fee);
        if (((BigDecimal)acc[2]).subtract(total).compareTo(new BigDecimal(acc[0].equals("PREMIUM") ? "-500.00" : "0.00")) < 0)
            return l.getProc().reject("TRANSFER", f[1], "INSUFFICIENT_FUNDS", "balance " + acc[2] + " " + acc[1] + ", needed " + total + " " + acc[1]);
        acc[2] = ((BigDecimal)acc[2]).subtract(total);
        to[2] = ((BigDecimal)to[2]).add(CurrencyConverter.convert(amt, (String)acc[1], (String)to[1], (String)acc[0]));
        l.getDailyUsage().computeIfAbsent(f[1], k -> new HashMap<>()).merge(f[2], amt, BigDecimal::add);
        Utils.addFee(l.getFees(), f[1], (String)acc[1], fee);
        return l.finalize(f[0], f[1], fee, (String)acc[1]);
    }
}

