import com.rustyledger.Ledger;
import java.math.BigDecimal;
import java.util.*;

public class LedgerImpl implements Ledger {
    private final Map<String, Object[]> accounts = new HashMap<>();
    private final Map<String, String[]> txs = new LinkedHashMap<>();
    private final List<String> audit = new ArrayList<>();
    private final Map<String, int[]> counts = new HashMap<>();
    private final Map<String, Map<String, BigDecimal>> dailyFees = new HashMap<>();
    private int auditSeq = 0, txSeq = 0;
    private final InstructionProcessor proc = new InstructionProcessor(this);

    public void openAccount(String id, String tier, String currency, String balance) {
        if (id == null || id.isEmpty() || id.contains("|") || !Set.of("STANDARD", "PREMIUM", "STAFF").contains(tier) || !Set.of("PLN", "EUR", "USD").contains(currency) || balance == null || !balance.matches("\\d+(\\.\\d{1,2})?")) throw new IllegalArgumentException();
        if (accounts.containsKey(id)) throw new IllegalStateException();
        accounts.put(id, new Object[]{tier, currency, new BigDecimal(balance).setScale(2)});
    }

    public String balance(String id) {
        Object[] a = accounts.get(id);
        if (a == null) throw new IllegalArgumentException();
        return a[2] + " " + a[1];
    }

    public List<String> auditLog() { return new ArrayList<>(audit); }

    public String submit(String line) { return proc.process(line); }

    public String dailyReport(String date) {
        int[] c = counts.getOrDefault(date, new int[2]);
        Map<String, BigDecimal> f = dailyFees.get(date);
        return "REPORT " + date + "\nok: " + c[0] + "\nrejected: " + c[1] + "\nfees: " + (f == null || f.isEmpty() ? "none" : format(f));
    }

    public String executeReversal(String date, String txId, String[] tx) {
        String[] original = txs.get(txId);
        Object[] from = accounts.get(original[2]);
        Object[] to = accounts.get(original[3]);
        BigDecimal amt = new BigDecimal(original[4]);
        BigDecimal fee = new BigDecimal(original[6]);
        from[2] = ((BigDecimal)from[2]).add(amt);
        if (original[0].equals("TRANSFER")) {
            BigDecimal converted = CurrencyConverter.convert(amt, (String)original[5], (String)to[1], (String)from[0]);
            to[2] = ((BigDecimal)to[2]).subtract(converted);
            if (from[0].equals("PREMIUM")) {
                from[2] = ((BigDecimal)from[2]).add(fee);
                Utils.addFee(dailyFees, date, (String)from[1], fee.negate());
            }
        }
        int n = ++txSeq;
        txs.put("REV-" + txId, new String[]{"REVERSE", date, txId});
        audit.add(String.format("%03d  REVERSE %s OK TX-%06d reversed %s", ++auditSeq, date, n, txId));
        counts.computeIfAbsent(date, k -> new int[2])[0]++;
        return "OK TX-" + String.format("%06d", n) + " reversed " + txId;
    }

    private String format(Map<String, BigDecimal> f) {
        StringBuilder sb = new StringBuilder();
        for (var e : new TreeMap<>(f).entrySet()) sb.append(sb.length() == 0 ? "" : ", ").append(e.getValue()).append(" ").append(e.getKey());
        return sb.toString();
    }

    public Map<String, Object[]> getAccounts() { return accounts; }
    public Map<String, String[]> getTxs() { return txs; }
    public List<String> getAudit() { return audit; }
    public Map<String, int[]> getCounts() { return counts; }
    public Map<String, Map<String, BigDecimal>> getFees() { return dailyFees; }
    public int nextAudit() { return ++auditSeq; }
    public int nextTx() { return ++txSeq; }
    public InstructionProcessor getProc() { return proc; }
}

